import re
import sys

def validate_username(username):
    if not isinstance(username, str):
        raise ValueError("Username must be a string")
    username = username.strip()
    if len(username) < 3 or len(username) > 20:
        raise ValueError("Username must be between 3 and 20 characters")
    if not re.match(r'^[a-zA-Z0-9_]+$', username):
        raise ValueError("Username can only contain letters, numbers, and underscores")
    return username

def validate_integer(value, min_val, max_val):
    try:
        num = int(value)
    except (ValueError, TypeError):
        raise ValueError("Input must be a valid integer")
    if num < min_val or num > max_val:
        raise ValueError(f"Number must be between {min_val} and {max_val}")
    return num

def validate_choice(choice, valid_choices):
    if not isinstance(choice, str):
        raise ValueError("Choice must be a string")
    choice = choice.strip().lower()
    if choice not in valid_choices:
        raise ValueError(f"Choice must be one of: {', '.join(valid_choices)}")
    return choice

def validate_text(text, max_length=1000):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    if len(text) > max_length:
        raise ValueError(f"Text too long (max {max_length} characters)")
    return text

def calculate_factorial(n):
    if not isinstance(n, int):
        raise ValueError("Input must be an integer")
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if n > 20:
        raise ValueError("Number too large for factorial calculation (max 20)")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def reverse_string(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    if len(text) > 1000:
        raise ValueError("Text too long (max 1000 characters)")
    return text[::-1]

def is_palindrome(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    cleaned = re.sub(r'[^a-zA-Z0-9]', '', text.lower())
    if len(cleaned) > 1000:
        raise ValueError("Text too long (max 1000 characters)")
    return cleaned == cleaned[::-1]

def get_validated_input(prompt, validator, *args):
    while True:
        try:
            user_input = input(prompt)
            return validator(user_input, *args)
        except ValueError as e:
            print(f"Invalid input: {e}. Please try again.")
        except KeyboardInterrupt:
            print("\nOperation cancelled.")
            sys.exit(0)

